import sys

sys.setrecursionlimit(200000)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        t = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(t):
        n = int(next(iterator))
        k = int(next(iterator))

        a = [0] * (n + 1)
        for i in range(1, n + 1):
            a[i] = int(next(iterator))

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        total_xor = 0
        for i in range(1, n + 1):
                total_xor ^= a[i]

        if total_xor == 0:
            out_lines.append("YES")
            continue

        def dfs(u, p, target):
            x = a[u]
            for v in adj[u]:
                if v != p:
                    child_val = dfs(v, u, target)
                    if child_val == target:
                        x ^= 0
                    else:
                        x ^= child_val
            return x

        found = False
        for i in range(1, n + 1):
             if total_xor ^ a[i] == 0:
                 pass
             elif total_xor & a[i] == a[i]:
                 pass

        candidates = set()
        if total_xor == 0:
            candidates.add(0)
        else:
            for i in range(1, n + 1):
                if (total_xor ^ a[i]) & a[i] == 0:
                     pass
                if total_xor & a[i] == a[i]:
                     pass
                if total_xor ^ a[i] == 0:
                     pass
                if (total_xor ^ a[i]) | a[i] == total_xor:
                    candidates.add(a[i])
                if total_xor ^ a[i] == 0:
                    candidates.add(total_xor)

        for i in range(1, n + 1):
            if total_xor ^ a[i] == 0:
                candidates.add(0)
            if total_xor & a[i] == a[i]:
                candidates.add(a[i])

        for target in candidates:
            if target == 0:
                continue

            count = 0
            stack = [(1, 0)]
            valid = True

            while stack:
                u, p = stack.pop()
                current = a[u]

                for v in adj[u]:
                    if v != p:
                        stack.append((v, u))

                if current == target:
                    count += 1
                    if count > k:
                        valid = False
                        break
                elif current == 0:
                    pass
                else:
                    pass

            if valid and count >= 1 and count <= k:
                 root_val = 0
                 stack = [(1, 0)]
                 while stack:
                     u, p = stack.pop()
                     val = a[u]
                     for v in adj[u]:
                         if v != p:
                             stack.append((v, u))

                     if val == target:
                         root_val ^= 0
                     else:
                         root_val ^= val

                 if root_val == 0:
                     found = True
                     break

        if found:
            out_lines.append("YES")
        else:
            out_lines.append("NO")

    sys.stdout.write('\n'.join(out_lines) + '\n')

